const W=10,H=10,SHIPS=[5,4,3,3,2];
// количество размещений одного корабля
let total=1; for(const L of SHIPS){ total*= (H*(W-L+1) + W*(H-L+1)); }
console.log('ordered placements ignoring overlap:', total.toExponential(3));
// доля без пересечений — Монте-Карло
function rnd(n){return Math.floor(Math.random()*n);}
let ok=0,N=2000000;
for(let t=0;t<N;t++){
  const occ=new Uint8Array(100); let good=true;
  for(const L of SHIPS){
    const horiz=Math.random()<0.5;
    let r,c; if(horiz){r=rnd(H);c=rnd(W-L+1);}else{r=rnd(H-L+1);c=rnd(W);}
    for(let i=0;i<L;i++){const cell=horiz?r*W+c+i:(r+i)*W+c; if(occ[cell]){good=false;break;} occ[cell]=1;}
    if(!good)break;
  }
  if(good)ok++;
}
const frac=ok/N;
console.log('overlap-free fraction ~', frac.toFixed(5));
console.log('distinct fleet arrangements ~', (total*frac).toExponential(3));
console.log('divided by ship-symmetry (two 3s):', (total*frac/2).toExponential(3));
"

