// Подбор конфигурации, дающей стартовый счёт около 1.4e7
function est(W,H,SHIPS,N=400000){
  let total=1; for(const L of SHIPS) total*= (H*(W-L+1)+W*(H-L+1));
  function rnd(n){return Math.floor(Math.random()*n);}
  let ok=0;
  for(let t=0;t<N;t++){
    const occ=new Uint8Array(W*H); let good=true;
    for(const L of SHIPS){
      const hz=Math.random()<0.5; let r,c;
      if(hz){r=rnd(H);c=rnd(W-L+1);}else{r=rnd(H-L+1);c=rnd(W);}
      for(let i=0;i<L;i++){const cell=hz?r*W+c+i:(r+i)*W+c; if(occ[cell]){good=false;break;} occ[cell]=1;}
      if(!good)break;
    }
    if(good)ok++;
  }
  // делим на перестановки одинаковых длин
  const cnt={}; for(const L of SHIPS) cnt[L]=(cnt[L]||0)+1;
  let sym=1; for(const k in cnt){ for(let i=2;i<=cnt[k];i++) sym*=i; }
  return total*ok/N/sym;
}
const cfgs=[
 [10,10,[5,4,3,3,2]],
 [8,8,[4,3,3,2]],
 [8,8,[5,4,3,2]],
 [8,8,[4,3,2,2]],
 [7,7,[4,3,3,2]],
 [8,8,[4,3,3,2,2]],
];
for(const [W,H,S] of cfgs) console.log(W+'x'+H, JSON.stringify(S), '->', est(W,H,S).toExponential(3));
"

node -e "
const W=8,H=8,N=W*H,SHIPS=[4,3,3,2];
// все размещения корабля длины L как битовые маски (BigInt дорог — берём два Uint32)
function placements(L){const out=[];
 for(let r=0;r<H;r++)for(let c=0;c+L<=W;c++){let lo=0,hi=0;for(let i=0;i<L;i++){const b=r*W+c+i; if(b<32)lo|=1<<b; else hi|=1<<(b-32);} out.push([lo>>>0,hi>>>0]);}
 for(let r=0;r+L<=H;r++)for(let c=0;c<W;c++){let lo=0,hi=0;for(let i=0;i<L;i++){const b=(r+i)*W+c; if(b<32)lo|=1<<b; else hi|=1<<(b-32);} out.push([lo>>>0,hi>>>0]);}
 return out;}
const PL=SHIPS.map(placements);
function countAll(emptyLo,emptyHi,hitLo,hitHi,limit){
 let n=0, nodes=0;
 const K=SHIPS.length;
 (function dfs(i,occLo,occHi,startIdx){
   if(n>=limit) return;
   if(i===K){ if(((hitLo&~occLo)===0)&&((hitHi&~occHi)===0)) n++; return; }
   const list=PL[i];
   // одинаковые длины -> запрет перестановок: индекс не убывает
   const same = i>0 && SHIPS[i]===SHIPS[i-1];
   for(let j=same?startIdx:0;j<list.length;j++){
     const [lo,hi]=list[j];
     if((lo&occLo)||(hi&occHi)) continue;
     if((lo&emptyLo)||(hi&emptyHi)) continue;
     nodes++;
     dfs(i+1,(occLo|lo)>>>0,(occHi|hi)>>>0,j+1);
     if(n>=limit) return;
   }
 })(0,0,0,0);
 return {n,nodes};
}
let t=Date.now();
let r=countAll(0,0,0,0,1e18);
console.log('старт: точный счёт =',r.n,' узлов=',r.nodes,' время=',(Date.now()-t)+'мс');
// середина: 12 промахов + 3 попадания
function mask(cells){let lo=0,hi=0;for(const b of cells){if(b<32)lo|=1<<b;else hi|=1<<(b-32);}return [lo>>>0,hi>>>0];}
const misses=[0,3,7,9,14,17,22,27,33,40,48,55,60,63];
const hits=[19,20,44];
const [eL,eH]=mask(misses),[hL,hH]=mask(hits);
t=Date.now(); r=countAll(eL,eH,hL,hH,1e18);
console.log('после 17 выстрелов: точный счёт =',r.n,' узлов=',r.nodes,' время=',(Date.now()-t)+'мс');
"

node -e "
const W=8,H=8,N=W*H,SHIPS=[4,3,3,2];
function placements(L){const out=[];
 for(let r=0;r<H;r++)for(let c=0;c+L<=W;c++){const cells=[];for(let i=0;i<L;i++)cells.push(r*W+c+i);out.push(cells);}
 for(let r=0;r+L<=H;r++)for(let c=0;c<W;c++){const cells=[];for(let i=0;i<L;i++)cells.push((r+i)*W+c);out.push(cells);}
 return out.map(cells=>{let lo=0,hi=0;for(const b of cells){if(b<32)lo|=1<<b;else hi|=1<<(b-32);}return {lo:lo>>>0,hi:hi>>>0,cells};});}
const PL=SHIPS.map(placements);
const K=SHIPS.length;
const marg=new Float64Array(N);
let total=0;
function dfs(i,occLo,occHi,startIdx,prefixCells,eL,eH,hL,hH){
 if(i===K-1){
   // последний корабль считаем оптом: здесь и счёт, и краевые вероятности
   const list=PL[i]; let leaves=0;
   const same=SHIPS[i]===SHIPS[i-1];
   for(let j=same?startIdx:0;j<list.length;j++){
     const p=list[j];
     if((p.lo&occLo)||(p.hi&occHi))continue;
     if((p.lo&eL)||(p.hi&eH))continue;
     const fLo=(occLo|p.lo)>>>0,fHi=(occHi|p.hi)>>>0;
     if((hL&~fLo)||(hH&~fHi))continue;
     leaves++;
     for(const c of p.cells) marg[c]+=1;
   }
   if(leaves){ total+=leaves; for(const c of prefixCells) marg[c]+=leaves; }
   return;
 }
 const list=PL[i]; const same=i>0&&SHIPS[i]===SHIPS[i-1];
 for(let j=same?startIdx:0;j<list.length;j++){
   const p=list[j];
   if((p.lo&occLo)||(p.hi&occHi))continue;
   if((p.lo&eL)||(p.hi&eH))continue;
   const np=prefixCells.concat(p.cells);
   dfs(i+1,(occLo|p.lo)>>>0,(occHi|p.hi)>>>0,j+1,np,eL,eH,hL,hH);
 }
}
let t=Date.now();
dfs(0,0,0,0,[],0,0,0,0);
console.log('старт: счёт=',total,' время=',(Date.now()-t)+'мс');
const p=[...marg].map(x=>x/total);
console.log('поле вероятностей, угол/центр:',p[0].toFixed(4),p[27].toFixed(4));
console.log('сумма вероятностей =',p.reduce((a,b)=>a+b,0).toFixed(3),'(ожидается 12 = 4+3+3+2)');
"
